proposal.css:
:root{--paper:#f7f4ee;--ink:#182d45;--ochre:#c8a567;--card:#fff;--radius:14px;--pad:clamp(20px,4vw,36px);--gap:18px}
*{box-sizing:border-box}
body{margin:0;background:var(--paper);color:var(--ink);font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;line-height:1.6;font-size:16px}
.wrap{max-width:640px;margin:0 auto;padding:var(--pad)}
header h1{font-size:clamp(1.6rem,5vw,2.2rem);margin:0 0 .3em;letter-spacing:.2px}
header p{margin:0 0 1.4em;max-width:46ch;color:#3a4a5e}
.card{background:var(--card);border:1px solid #e7e0d2;border-radius:var(--radius);padding:var(--pad);box-shadow:0 10px 30px rgba(24,45,69,.08)}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:var(--gap)}
.item{display:flex;align-items:center;gap:12px;min-height:44px}
.item svg{flex:0 0 auto}
.item .txt{display:flex;flex-direction:column;min-width:0}
.item .lbl{font-size:.78rem;text-transform:uppercase;letter-spacing:.06em;color:var(--ochre);font-weight:600}
.item a,.item span.val{font-size:1rem;color:var(--ink);text-decoration:none;overflow-wrap:anywhere;min-height:44px;display:inline-flex;align-items:center}
.item a:hover{color:var(--ochre)}
.social{grid-column:1/-1;display:flex;align-items:center;gap:12px;min-height:44px}
.social a{display:inline-flex;align-items:center;gap:8px;min-height:44px;padding:0 14px;border:1px solid var(--ochre);border-radius:999px;color:var(--ink);text-decoration:none;font-weight:600}
.social a:hover{background:var(--ochre);color:#fff}
footer{margin-top:1.4em;font-size:.85rem;color:#6b7a8c}
a:focus-visible,button:focus-visible{outline:3px solid var(--ochre);outline-offset:2px;border-radius:6px}
@media(max-width:700px){.grid{grid-template-columns:1fr}}
